  "charta.cabinet.eyesExample": ["例如：琥珀色", "例如：琥珀色", "e.g. amber", "例：琥珀色", "예: 호박색"],
  "charta.cabinet.heightExample": ["例如：155cm", "例如：155cm", "e.g. 155 cm", "例：155cm", "예: 155cm"],
